{"discussion":"The InvalidWriteError class is already added and __all__ is updated. Now I need to add the validation logic in _write_section. Let me patch _write_section to call a new _validate_write_key helper that checks SECTCRE match and delimiter containment.","operation":{"action":"patch","path":"Lib/configparser.py","old":"    def _write_section(self, fp, section_name, section_items, delimiter):
        """Write a single section to the specified `fp`."""
        fp.write("[{}]\n".format(section_name))
        for key, value in section_items:
            value = self._interpolation.before_write(self, section_name, key,
                                                     value)","new":"    def _validate_write_key(self, key):
        """Check that an option name is safe for writing.

        Raise InvalidWriteError if the key would produce ambiguous output
        when written to a file.
        """
        if self.SECTCRE.match(key):
            raise InvalidWriteError(key)
        for d in self._delimiters:
            if d in key:
                raise InvalidWriteError(key)

    def _write_section(self, fp, section_name, section_items, delimiter):
        """Write a single section to the specified `fp`."""
        fp.write("[{}]\n".format(section_name))
        for key, value in section_items:
            self._validate_write_key(key)
            value = self._interpolation.before_write(self, section_name, key,
                                                     value)","expected_candidate_id":"04a50457f892f442980a20263144afa3fb8992fb5841ced8922ffce0dcb559d3","expected_file_sha256":"d74cb6e03c077da993c311646991081db47485b49f1c5c52d9e5679f3fcd46da"}}
